const state = {
  releases: loadReleases(),
};

const refs = {};

document.addEventListener("DOMContentLoaded", init);

function init() {
  refs.adminLogin = document.getElementById("adminLogin");
  refs.adminDashboard = document.getElementById("adminDashboard");
  refs.loginForm = document.getElementById("loginForm");
  refs.loginStatus = document.getElementById("loginStatus");
  refs.releaseForm = document.getElementById("releaseForm");
  refs.releaseStatus = document.getElementById("releaseStatus");
  refs.adminReleaseList = document.getElementById("adminReleaseList");
  refs.importData = document.getElementById("importData");

  bindEvents();
  if (sessionStorage.getItem(ADMIN_SESSION_KEY) === "1") {
    showAdminDashboard();
  }
}

function bindEvents() {
  refs.loginForm.addEventListener("submit", (event) => {
    event.preventDefault();
    const user = document.getElementById("loginUser").value.trim();
    const pass = document.getElementById("loginPass").value;

    if (user === ADMIN_USER && pass === ADMIN_PASS) {
      sessionStorage.setItem(ADMIN_SESSION_KEY, "1");
      refs.loginStatus.textContent = "";
      showAdminDashboard();
      return;
    }

    refs.loginStatus.textContent = "wrong login or password";
  });

  refs.releaseForm.addEventListener("submit", handleReleaseSubmit);
  document.getElementById("exportData").addEventListener("click", exportData);
  document.getElementById("resetData").addEventListener("click", resetData);
  refs.importData.addEventListener("change", importData);
}

function showAdminDashboard() {
  refs.adminLogin.hidden = true;
  refs.adminDashboard.hidden = false;
  renderAdminReleases();
}

async function handleReleaseSubmit(event) {
  event.preventDefault();
  refs.releaseStatus.textContent = "saving...";

  const file = document.getElementById("releaseImageFile").files[0];
  const url = document.getElementById("releaseImageUrl").value.trim();
  let image = url;

  try {
    if (file) {
      image = await compressImage(file);
    }

    const release = {
      id: createId(),
      title: document.getElementById("releaseTitle").value.trim(),
      artists: document.getElementById("releaseArtists").value.trim(),
      genre: document.getElementById("releaseGenre").value.trim(),
      date: document.getElementById("releaseDate").value,
      image,
      link: document.getElementById("releaseLink").value.trim(),
      isPreRelease: document.getElementById("releaseIsPreRelease").checked,
    };

    state.releases = [release, ...state.releases];
    saveReleases(state.releases);
    refs.releaseForm.reset();
    document.getElementById("releaseArtists").value = "winver";
    refs.releaseStatus.textContent = "saved";
    renderAdminReleases();
  } catch (error) {
    refs.releaseStatus.textContent =
      error.name === "QuotaExceededError"
        ? "image is too large for local browser storage"
        : "could not save release";
  }
}

function renderAdminReleases() {
  refs.adminReleaseList.replaceChildren();

  getSortedReleases().forEach((release) => {
    const row = document.createElement("article");
    row.className = "admin-release-item";

    const thumb = document.createElement("div");
    thumb.className = "admin-thumb";
    if (release.image) {
      const img = document.createElement("img");
      img.alt = "";
      img.src = release.image;
      thumb.append(img);
    } else {
      thumb.textContent = "cover";
    }

    const info = document.createElement("div");
    const title = document.createElement("h3");
    title.textContent = release.title;
    if (release.isPreRelease) {
      const badge = document.createElement("span");
      badge.className = "badge";
      badge.style.marginLeft = "8px";
      badge.textContent = "pre-release";
      title.append(badge);
    }
    const meta = document.createElement("p");
    meta.textContent = `${release.artists} / ${release.genre} / ${formatDate(release.date)}`;
    if (release.link) {
      meta.append(" / ");
      const linkEl = document.createElement("a");
      linkEl.href = release.link;
      linkEl.target = "_blank";
      linkEl.rel = "noreferrer";
      linkEl.textContent = "listen";
      meta.append(linkEl);
    }

    const remove = document.createElement("button");
    remove.className = "line-button danger";
    remove.type = "button";
    remove.textContent = "delete";
    remove.addEventListener("click", () => {
      state.releases = state.releases.filter((item) => item.id !== release.id);
      saveReleases(state.releases);
      renderAdminReleases();
    });

    row.append(thumb, info, remove);
    refs.adminReleaseList.append(row);
  });
}

function getSortedReleases() {
  return [...state.releases].sort((a, b) => dateValue(b.date) - dateValue(a.date));
}

function loadReleases() {
  try {
    const stored = localStorage.getItem(RELEASES_KEY);
    if (!stored) return [...DEFAULT_RELEASES];
    const parsed = JSON.parse(stored);
    if (!Array.isArray(parsed)) return [...DEFAULT_RELEASES];
    return parsed.map(normalizeRelease).filter(Boolean);
  } catch {
    return [...DEFAULT_RELEASES];
  }
}

function saveReleases(releases) {
  localStorage.setItem(RELEASES_KEY, JSON.stringify(releases));
}

function normalizeRelease(value) {
  if (!value || typeof value !== "object") return null;
  const title = String(value.title || "").trim();
  const artists = String(value.artists || "").trim();
  const genre = String(value.genre || "").trim();
  const date = String(value.date || "").trim();
  if (!title || !artists || !genre || !date) return null;

  return {
    id: String(value.id || createId()),
    title,
    artists,
    genre,
    date,
    image: String(value.image || ""),
    link: String(value.link || ""), // <-- Добавлено
  };
}

function exportData() {
  const blob = new Blob([JSON.stringify(getSortedReleases(), null, 2)], {
    type: "application/json",
  });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = "winver-releases.json";
  link.click();
  URL.revokeObjectURL(url);
}

async function importData(event) {
  const file = event.target.files[0];
  if (!file) return;

  try {
    const text = await file.text();
    const parsed = JSON.parse(text);
    if (!Array.isArray(parsed)) throw new Error("Invalid data");
    state.releases = parsed.map(normalizeRelease).filter(Boolean);
    saveReleases(state.releases);
    renderAdminReleases();
  } catch {
    alert("Could not import JSON");
  } finally {
    event.target.value = "";
  }
}

function resetData() {
  state.releases = [...DEFAULT_RELEASES];
  saveReleases(state.releases);
  renderAdminReleases();
}

function compressImage(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = reject;
    reader.onload = () => {
      const image = new Image();
      image.onerror = reject;
      image.onload = () => {
        const maxSide = 1100;
        const ratio = Math.min(1, maxSide / Math.max(image.width, image.height));
        const canvas = document.createElement("canvas");
        canvas.width = Math.max(1, Math.round(image.width * ratio));
        canvas.height = Math.max(1, Math.round(image.height * ratio));
        const context = canvas.getContext("2d");
        context.drawImage(image, 0, 0, canvas.width, canvas.height);
        resolve(canvas.toDataURL("image/jpeg", 0.84));
      };
      image.src = reader.result;
    };
    reader.readAsDataURL(file);
  });
}

function formatDate(date) {
  const value = dateValue(date);
  if (!value) return date;
  return new Intl.DateTimeFormat("ru-RU", {
    year: "numeric",
    month: "short",
    day: "2-digit",
  }).format(new Date(value));
}

function dateValue(date) {
  const value = Date.parse(`${date}T00:00:00`);
  return Number.isFinite(value) ? value : 0;
}

function createId() {
  if (window.crypto && crypto.randomUUID) return crypto.randomUUID();
  return `release-${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

async function saveReleasesToServer(currentReleases) {
    try {
        const response = await fetch('save_releases.php', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify(currentReleases)
        });

        const result = await response.json();
        
        if (result.status === 'success') {
            alert('Releases saved successfully to the server.');
        } else {
            alert('Server error: ' + result.message);
        }
    } catch (error) {
        console.error('Error sending data:', error);
    }
}
